mapper.select:
SELECT dept_name AS deptName, NVL(SUM(check_count), 0) AS checkCount, ROUND(AVG(NVL(on_time_rate, 0)), 2) || '%' AS onTimeRate, ROUND(AVG(NVL(wait_time, 0)), 2) AS waitTime, ROUND(AVG(NVL(avg_wait_late, 0)), 2) AS avgWaitLate, ROUND(AVG(NVL(avg_report_time, 0)), 2) AS avgReportTime FROM TR_MEDTECH_DTL WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
GROUP BY dept_name ORDER BY checkCount DESC
